-- GUS-242 / ADR-003 layer 2 — the dish names.
--
-- Generated by scripts/load_dish_names.py from /tmp/dish_names.json.
-- Do not hand-edit: regenerate.
--
-- 1373 names, seeded from Wikidata (CC0): the sitelink titles
-- for the endonyms, P1705 for the native labels, P2561 for the
-- romanizations and P1448 for the official names, plus the item's
-- labels for the exonyms.
--
-- ENGLISH IS NOT HERE: the dish's English name is its canonical_name
-- in the dishes table, which is what the ADR asks for - the base
-- table holds the canonical name and this table holds the others.
-- (123 English names were dropped for that reason.)
--
-- The dish_id is resolved by a subquery on the dish's slug, so the
-- SQL does not depend on the UUIDs being stable between the export
-- and the apply.
--
-- Idempotent: re-running changes no row.

\set ON_ERROR_STOP on

-- IDEMPOTENT
--
-- The guard is TRUE when the migration still needs to run - that is,
-- when the names are not yet there.
SELECT
  NOT (
    (SELECT count(*) FROM dish_names) >= 1000
    AND
    (SELECT count(DISTINCT dish_id) FROM dish_names) >= 100
  ) AS need_to_run \gset
\if :need_to_run
\echo 'GUS-242: the dish names are not yet applied - applying them'

